SELECT DISTINCTROW ORPR98.CODPROD, ANART.DESPROD, ORPR98.FINITURA, ORPR98.SPESSORE, ORPR98.ALTEZZA, ORPR98.LARGHEZZA, ORPR98.ORIGINE, ORPR98.ORDINE, ORPR98.MACCHINA, ORPR98.NUMCOMM, ANCLI_1.DESCLI, ORPR98.RETE, ORPR98.CODCLI, ANCLI.DESCLI, ORPR98.DATAENT, ORPR98.QTAUSC
FROM ((ANCLI RIGHT JOIN (ANART INNER JOIN ORPR98 ON ANART.CODPROD = ORPR98.CODPROD) ON ANCLI.CODCLI = ORPR98.CODCLI) LEFT JOIN BOLLE ON ORPR98.NUMCOMM = BOLLE.CODRIC) LEFT JOIN ANCLI AS ANCLI_1 ON BOLLE.CODCLI = ANCLI_1.CODCLI;
